#include "evaluator.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
typedef struct Entry{char*name;Value value;bool mutable;struct Entry*next;}Entry;struct Environment{Entry*head;};static char*dupstr(const char*s){size_t n=strlen(s);char*p=malloc(n+1U);if(p)memcpy(p,s,n+1U);return p;}
Value value_null(void){Value v={VALUE_NULL,{.integer=0}};return v;}Value value_bool(bool b){Value v={VALUE_BOOL,{.boolean=b}};return v;}Value value_int(int64_t i){Value v={VALUE_INT,{.integer=i}};return v;}Value value_float(double f){Value v={VALUE_FLOAT,{.floating=f}};return v;}Value value_string_copy(const char*s){Value v={VALUE_STRING,{.string=s?dupstr(s):NULL}};if(s&&!v.as.string)v.type=VALUE_NULL;return v;}Value value_clone(const Value*v){if(!v)return value_null();if(v->type==VALUE_STRING)return value_string_copy(v->as.string);return *v;}void value_free(Value*v){if(!v)return;if(v->type==VALUE_STRING)free(v->as.string);v->type=VALUE_NULL;v->as.integer=0;}void print_value(const Value*v){if(!v){printf("null");return;}switch(v->type){case VALUE_NULL:printf("null");break;case VALUE_BOOL:printf("%s",v->as.boolean?"true":"false");break;case VALUE_INT:printf("%lld",(long long)v->as.integer);break;case VALUE_FLOAT:printf("%.17g",v->as.floating);break;case VALUE_STRING:printf("%s",v->as.string?v->as.string:"");break;}}bool value_truthy(const Value*v){if(!v)return false;switch(v->type){case VALUE_NULL:return false;case VALUE_BOOL:return v->as.boolean;case VALUE_INT:return v->as.integer!=0;case VALUE_FLOAT:return v->as.floating!=0.0;case VALUE_STRING:return v->as.string&&v->as.string[0];}return false;}
Environment*env_new(void){return calloc(1,sizeof(Environment));}void env_free(Environment*e){if(!e)return;while(e->head){Entry*n=e->head->next;free(e->head->name);value_free(&e->head->value);free(e->head);e->head=n;}free(e);}bool env_define(Environment*e,const char*n,Value v,bool mut){if(!e||!n)return false;Entry*x=calloc(1,sizeof(*x));if(!x)return false;x->name=dupstr(n);x->value=value_clone(&v);x->mutable=mut;x->next=e->head;e->head=x;return x->name!=NULL;}Value*env_lookup(Environment*e,const char*n){for(Entry*x=e?e->head:NULL;x;x=x->next)if(!strcmp(x->name,n))return &x->value;return NULL;}bool env_assign(Environment*e,const char*n,const Value*v){for(Entry*x=e?e->head:NULL;x;x=x->next)if(!strcmp(x->name,n)){if(!x->mutable)return false;Value copy=value_clone(v);value_free(&x->value);x->value=copy;return true;}return false;}
static Value eval(Environment*e,const AstNode*n){if(!n)return value_null();switch(n->type){case AST_INTEGER:return value_int(n->as.integer);case AST_FLOAT:return value_float(n->as.floating);case AST_BOOLEAN:return value_bool(n->as.boolean);case AST_NULL:return value_null();case AST_STRING:return value_string_copy(n->as.string);case AST_IDENTIFIER:{Value*v=env_lookup(e,n->as.identifier);return value_clone(v);}case AST_LET:{Value v=eval(e,n->as.declaration.value);env_define(e,n->as.declaration.name,v,n->as.declaration.mutable);return v;}case AST_ASSIGNMENT:{Value v=eval(e,n->as.assignment.value);if(!env_assign(e,n->as.assignment.name,&v)){value_free(&v);return value_null();}return v;}case AST_RETURN:return eval(e,n->as.return_statement.value);case AST_EXPRESSION_STATEMENT:return eval(e,n->as.expression_statement.expression);case AST_PROGRAM:case AST_BLOCK:{Value last=value_null();for(size_t i=0;i<n->as.block.statements.count;i++){Value cur=eval(e,n->as.block.statements.items[i]);value_free(&last);last=cur;}return last;}case AST_IF:{Value c=eval(e,n->as.if_statement.condition);bool b=value_truthy(&c);value_free(&c);return eval(e,b?n->as.if_statement.then_branch:n->as.if_statement.else_branch);}case AST_UNARY:{Value v=eval(e,n->as.unary.operand);if(n->as.unary.operator_type==TOKEN_BANG){bool b=!value_truthy(&v);value_free(&v);return value_bool(b);}if(n->as.unary.operator_type==TOKEN_MINUS&&v.type==VALUE_INT){v.as.integer=-v.as.integer;return v;}if(n->as.unary.operator_type==TOKEN_MINUS&&v.type==VALUE_FLOAT){v.as.floating=-v.as.floating;return v;}value_free(&v);return value_null();}case AST_BINARY:{Value a=eval(e,n->as.binary.left),b=eval(e,n->as.binary.right);TokenType o=n->as.binary.operator_type;if(a.type==VALUE_INT&&b.type==VALUE_INT){int64_t r=0;bool ok=true;switch(o){case TOKEN_PLUS:r=a.as.integer+b.as.integer;break;case TOKEN_MINUS:r=a.as.integer-b.as.integer;break;case TOKEN_STAR:r=a.as.integer*b.as.integer;break;case TOKEN_SLASH:if(!b.as.integer)ok=false;else r=a.as.integer/b.as.integer;break;default:ok=false;}value_free(&a);value_free(&b);return ok?value_int(r):value_null();}if(o==TOKEN_EQUAL_EQUAL||o==TOKEN_BANG_EQUAL){bool q=false;if(a.type==b.type&&a.type==VALUE_INT)q=a.as.integer==b.as.integer;else if(a.type==b.type&&a.type==VALUE_BOOL)q=a.as.boolean==b.as.boolean;else if(a.type==b.type&&a.type==VALUE_STRING)q=!strcmp(a.as.string,b.as.string);else if(a.type==b.type&&a.type==VALUE_NULL)q=true;value_free(&a);value_free(&b);return value_bool(o==TOKEN_EQUAL_EQUAL?q:!q);}value_free(&a);value_free(&b);return value_null();}default:return value_null();}}
Value eval_ast(Environment*e,const AstNode*n){return eval(e,n);}
